import { Routes } from '@angular/router';

export const routes: Routes = [
	{ path: '', redirectTo: 'recipes', pathMatch: 'full' },
	{
		path: 'recipes',
		loadChildren: () => import('./recipes/recipes-module').then(m => m.RecipesModule),
	},
	{
		path: 'auth',
		loadChildren: () => import('./auth/auth-module').then(m => m.AuthModule),
	},
	{
		path: 'categories',
		loadChildren: () => import('./categories/categories-module').then(m => m.CategoriesModule),
	},
	{
		path: 'admin',
		loadChildren: () => import('./admin/admin-module').then(m => m.AdminModule),
	},
	{
		path: 'profile',
		loadChildren: () => import('./user/user-module').then(m => m.UserModule),
	},
	{ path: '**', redirectTo: 'recipes' },
];

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';

import { RecipeList } from './recipe-list/recipe-list';
import { RecipeDetail } from './recipe-detail/recipe-detail';
import { RecipeForm } from './recipe-form/recipe-form';
import { IngredientList } from './ingredient-list/ingredient-list';
import { RecipeSearch } from './recipe-search/recipe-search';

const routes: Routes = [
  { path: '', component: RecipeList },
  { path: 'new', component: RecipeForm },
  { path: ':id', component: RecipeDetail },
  { path: ':id/edit', component: RecipeForm },
];

@NgModule({
  declarations: [RecipeList, RecipeDetail, RecipeForm, IngredientList, RecipeSearch],
  imports: [CommonModule, RouterModule.forChild(routes)],
})
export class RecipesModule {}

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';

import { Login } from './login/login';
import { Register } from './register/register';

const routes: Routes = [
  { path: '', redirectTo: 'login', pathMatch: 'full' },
  { path: 'login', component: Login },
  { path: 'register', component: Register },
];

@NgModule({
  declarations: [Login, Register],
  imports: [CommonModule, RouterModule.forChild(routes)],
})
export class AuthModule {}

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';

import { CategoryList } from './category-list/category-list';
import { CategoryForm } from './category-form/category-form';
import { CategoryFilter } from './category-filter/category-filter';

const routes: Routes = [
  { path: '', component: CategoryList },
  { path: 'new', component: CategoryForm },
  { path: ':id/edit', component: CategoryForm },
];

@NgModule({
  declarations: [CategoryList, CategoryForm, CategoryFilter],
  imports: [CommonModule, RouterModule.forChild(routes)],
})
export class CategoriesModule {}

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';

import { RatingForm } from './rating-form/rating-form';
import { RatingList } from './rating-list/rating-list';
import { RatingItem } from './rating-item/rating-item';

const routes: Routes = [
  { path: '', component: RatingList },
  { path: 'new', component: RatingForm },
];

@NgModule({
  declarations: [RatingForm, RatingList, RatingItem],
  imports: [CommonModule, RouterModule.forChild(routes)],
})
export class RatingsModule {}

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';

import { AdminDashboard } from './admin-dashboard/admin-dashboard';
import { RecipeManagement } from './recipe-management/recipe-management';
import { CategoryManagement } from './category-management/category-management';
import { RatingModeration } from './rating-moderation/rating-moderation';

const routes: Routes = [
  { path: '', component: AdminDashboard },
  { path: 'recipes', component: RecipeManagement },
  { path: 'categories', component: CategoryManagement },
  { path: 'ratings', component: RatingModeration },
];

@NgModule({
  declarations: [AdminDashboard, RecipeManagement, CategoryManagement, RatingModeration],
  imports: [CommonModule, RouterModule.forChild(routes)],
})
export class AdminModule {}

import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';

import { Profile } from './profile/profile';
import { MyRatings } from './my-ratings/my-ratings';

const routes: Routes = [
  { path: '', component: Profile },
  { path: 'ratings', component: MyRatings },
];

@NgModule({
  declarations: [Profile, MyRatings],
  imports: [CommonModule, RouterModule.forChild(routes)],
})
export class UserModule {}

