// Design tokens (SCSS variables + CSS custom properties)
// Central place for colors, spacing, typography, radii, shadows and breakpoints.

// Colors
$color-primary: #1976d2;
$color-primary-contrast: #ffffff;
$color-accent: #ff4081;
$color-warn: #f44336;
$color-surface: #ffffff;
$color-background: #f5f7fb;
$color-on-background: #212121;
$color-muted: #616161;

// Spacing scale
$space-xxs: 2px;
$space-xs: 4px;
$space-sm: 8px;
$space-md: 16px;
$space-lg: 24px;
$space-xl: 32px;
$space-xxl: 48px;

// Radii
$radius-sm: 4px;
$radius-md: 8px;
$radius-lg: 12px;

// Shadows
$shadow-1: 0 1px 3px rgba(0, 0, 0, 0.12);
$shadow-2: 0 4px 8px rgba(0, 0, 0, 0.08);

// Typography
$font-family-base: 'Roboto', 'Helvetica', 'Arial', sans-serif;
$font-size-base: 16px;
$line-height-base: 1.5;
$font-weight-regular: 400;
$font-weight-medium: 500;

$h1-size: 2.25rem;
$h2-size: 1.75rem;
$h3-size: 1.5rem;
$h4-size: 1.25rem;
$h5-size: 1rem;
$h6-size: 0.875rem;

// Breakpoints
$breakpoints: (
  xs: 0,
  sm: 600px,
  md: 960px,
  lg: 1280px,
  xl: 1920px
);

// Responsive mixin
@mixin respond($bp) {
  $min: map-get($breakpoints, $bp);
  @if $min != null and $min != 0 {
    @media (min-width: $min) {
      @content;
    }
  } @else if $min == 0 {
    @content;
  } @else {
    @warn "Unknown breakpoint `#{$bp}`.";
  }
}

// Export tokens as CSS custom properties for runtime usage in component styles
:root {
  /* colors */
  --color-primary: #{$color-primary};
  --color-primary-contrast: #{$color-primary-contrast};
  --color-accent: #{$color-accent};
  --color-warn: #{$color-warn};
  --color-surface: #{$color-surface};
  --color-background: #{$color-background};
  --text-high: #{$color-on-background};
  --text-muted: #{$color-muted};

  /* spacing */
  --space-xxs: #{$space-xxs};
  --space-xs: #{$space-xs};
  --space-sm: #{$space-sm};
  --space-md: #{$space-md};
  --space-lg: #{$space-lg};
  --space-xl: #{$space-xl};
  --space-xxl: #{$space-xxl};

  /* radii */
  --radius-sm: #{$radius-sm};
  --radius-md: #{$radius-md};
  --radius-lg: #{$radius-lg};

  /* shadows */
  --shadow-1: #{$shadow-1};
  --shadow-2: #{$shadow-2};

  /* typography */
  --font-family-base: #{$font-family-base};
  --font-size-base: #{$font-size-base};
  --line-height-base: #{$line-height-base};
  --h1-size: #{$h1-size};
  --h2-size: #{$h2-size};
  --h3-size: #{$h3-size};
  --h4-size: #{$h4-size};
  --h5-size: #{$h5-size};
  --h6-size: #{$h6-size};
}

@use './styles/tokens';

/* Global base styles */
html, body {
	height: 100%;
	margin: 0;
	padding: 0;
	font-family: var(--font-family-base);
	font-size: var(--font-size-base);
	line-height: var(--line-height-base);
	color: var(--text-high);
	background-color: var(--color-background);
}

a {
	color: var(--color-primary);
	text-decoration: none;
}

button {
	font-family: inherit;
}

