import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, FormArray, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { RECIPES, CATEGORIES, Recipe } from '../../in-memory';

@Component({
  selector: 'app-recipe-form',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './recipe-form.html',
  styleUrls: ['./recipe-form.scss'],
})
export class RecipeForm implements OnInit {
  form!: FormGroup;
  isEdit = false;
  recipeId?: string;
  categories = CATEGORIES;

  constructor(private fb: FormBuilder, private route: ActivatedRoute, private router: Router) {}

  ngOnInit(): void {
    this.form = this.fb.group({
      title: ['', Validators.required],
      description: [''],
      categoryId: ['', Validators.required],
      ingredients: this.fb.array([]),
    });

    this.route.paramMap.subscribe((params) => {
      const id = params.get('id');
      if (id) {
        this.isEdit = true;
        this.recipeId = id;
        this.loadRecipe(id);
      } else {
        // start with one empty ingredient row
        this.addIngredient();
      }
    });
  }

  get ingredients(): FormArray {
    return this.form.get('ingredients') as FormArray;
  }

  addIngredient(value?: { name: string; quantity: string }) {
    this.ingredients.push(
      this.fb.group({
        quantity: [value?.quantity ?? '', Validators.required],
        name: [value?.name ?? '', Validators.required],
      })
    );
  }

  removeIngredient(index: number) {
    this.ingredients.removeAt(index);
    if (this.ingredients.length === 0) this.addIngredient();
  }

  private loadRecipe(id: string) {
    const r = RECIPES.find((x) => x.id === id);
    if (!r) return;
    this.form.patchValue({ title: r.title, description: r.description, categoryId: r.categoryId });
    // clear and set ingredients
    while (this.ingredients.length) {
      this.ingredients.removeAt(0);
    }
    r.ingredients.forEach((ing) => this.addIngredient(ing));
  }

  save() {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }

    const v = this.form.value;
    if (this.isEdit && this.recipeId) {
      const idx = RECIPES.findIndex((r) => r.id === this.recipeId);
      if (idx !== -1) {
        RECIPES[idx] = {
          ...RECIPES[idx],
          title: v.title,
          description: v.description,
          categoryId: v.categoryId,
          ingredients: v.ingredients,
        } as Recipe;
        this.router.navigate(['/recipes', this.recipeId]);
        return;
      }
    }

    // create new
    const nextId = String(RECIPES.reduce((max, r) => Math.max(max, Number(r.id)), 0) + 1);
    const newRecipe: Recipe = {
      id: nextId,
      title: v.title,
      description: v.description,
      categoryId: v.categoryId,
      ingredients: v.ingredients,
      createdBy: '1',
      createdAt: new Date(),
    };
    RECIPES.push(newRecipe);
    this.router.navigate(['/recipes', nextId]);
  }

  cancel() {
    this.router.navigate(['/recipes']);
  }
}

.recipe-form {
	max-width: 780px;
	margin: var(--space-xxl) auto;
	padding: var(--space-md);
	background: var(--color-surface);
	border-radius: var(--radius-md);
	box-shadow: var(--shadow-1);
	display: flex;
	flex-direction: column;
	gap: var(--space-md);

	.title {
		margin: 0 0 var(--space-sm) 0;
		font-size: var(--h2-size);
	}

	.field {
		display: flex;
		flex-direction: column;
		gap: var(--space-xs);
	}

	input,
	textarea,
	select {
		padding: var(--space-sm);
		border-radius: var(--radius-sm);
		border: 1px solid rgba(0, 0, 0, 0.08);
		background: transparent;
		width: 100%;
		box-sizing: border-box;
	}

	.ingredients {
		display: flex;
		flex-direction: column;
		gap: var(--space-sm);

		.ingredient-row {
			display: flex;
			gap: var(--space-sm);
			align-items: center;

			input {
				flex: 1 1 auto;
			}

			.remove {
				background: transparent;
				border: none;
				color: var(--color-warn);
				cursor: pointer;
			}
		}
	}

	.actions {
		display: flex;
		gap: var(--space-sm);
		justify-content: flex-end;
	}

	.btn {
		padding: var(--space-xs) var(--space-md);
		border-radius: var(--radius-sm);
		border: none;
		cursor: pointer;
	}

	.btn.primary {
		background: var(--color-primary);
		color: var(--color-primary-contrast);
	}
}

