	border: 1px solid rgba(0, 0, 0, 0.12);
	background: transparent;
	width: 100%;
	box-sizing: border-box;
}

.error small {
	color: var(--color-warn);
	font-size: 0.85rem;
}

.actions {
	display: flex;
